namespace ghidra.app.util.headless;



using ghidra.util;

/**
 * Custom headless error logger which is used when log4j is disabled.
 */
class HeadlessErrorLogger : ErrorLogger {

	private PrintWriter logWriter;

	HeadlessErrorLogger(File logFile) {
		if (logFile != null) {
			setLogFile(logFile);
		}
	}

	void setLogFile(File logFile) {
		try {
			if (logFile == null) {
				if (logWriter != null) {
					writeLog("INFO", "File logging disabled");
					logWriter.close();
					logWriter = null;
				}
				return;
			}
			PrintWriter w = new PrintWriter(new FileWriter(logFile));
			if (logWriter != null) {
				writeLog("INFO ", "Switching log file to: " + logFile);
				logWriter.close();
			}
			logWriter = w;
		}
		catch (IOException e) {
			// This class is using its own error logging, do not use Msg here
			Console.Error.WriteLine("Failed to open log file " + logFile + ": " + e.getMessage());
		}
	}

	private void writeLog(string line) {
		if (logWriter == null) {
			return;
		}
		logWriter.println(line);
	}

	private void writeLog(string level, string[] lines) {
		if (logWriter == null) {
			return;
		}
		foreach (string line in lines) {
			writeLog(level + " " + line);
		}
		logWriter.flush();
	}

	private void writeLog(string level, string text) {
		if (logWriter == null) {
			return;
		}
		writeLog(level, chopLines(text));
	}

	private void writeLog(string level, string text, Throwable throwable) {
		if (logWriter == null) {
			return;
		}
		writeLog(level, chopLines(text));
		foreach (StackTraceElement element in throwable.getStackTrace()) {
			writeLog(level + " " + element.toString());
		}
		logWriter.flush();
	}

	private string[] chopLines(string text) {
		text = text.replace("\r", "");
		return text.split("\n");
	}

